<script setup lang="ts">
import { useSpacesDirectory } from '~/composables/projects/useSpacesDirectory'
definePageMeta({layout:'home'})
const search=ref(''),projectFilter=ref(''),sort=ref('recent')
const query=useSpacesDirectory()
const rows=computed(()=>{const term=search.value.trim().toLocaleLowerCase('ru');return (query.data.value||[]).filter(p=>!projectFilter.value||p.id===projectFilter.value).map(project=>({...project,spaces:project.spaces.filter(s=>!term||`${project.name} ${s.name} ${s.description}`.toLocaleLowerCase('ru').includes(term)).sort((a,b)=>sort.value==='name'?a.name.localeCompare(b.name,'ru'):sort.value==='oldest'?a.updated_at.localeCompare(b.updated_at):b.updated_at.localeCompare(a.updated_at))})).filter(p=>p.spaces.length||!term).sort((a,b)=>sort.value==='project'?a.name.localeCompare(b.name,'ru'):sort.value==='name'?a.name.localeCompare(b.name,'ru'):sort.value==='oldest'?(a.spaces[0]?.updated_at||'').localeCompare(b.spaces[0]?.updated_at||''):(b.spaces[0]?.updated_at||'').localeCompare(a.spaces[0]?.updated_at||''))})
</script>
<template><main class="spaces-directory"><NuxtLink to="/" class="directory-back">← К приложениям</NuxtLink><header><div><span class="eyebrow">КОМАНДНАЯ РАБОТА</span><h1><UIcon name="i-lucide-orbit"/>Пространства</h1><p>Выберите проект и продолжите работу на доске.</p></div><NuxtLink to="/projects">Все проекты ↗</NuxtLink></header><div class="directory-filters"><UInput v-model="search" icon="i-lucide-search" placeholder="Поиск по проектам и пространствам" class="directory-search"/><select v-model="projectFilter" aria-label="Проект"><option value="">Все проекты</option><option v-for="project in query.data.value" :key="project.id" :value="project.id">{{project.name}}</option></select><select v-model="sort" aria-label="Сортировка"><option value="recent">Сначала обновлённые</option><option value="oldest">Сначала старые</option><option value="name">По названию</option><option value="project">По проекту</option></select></div><UAlert v-if="query.error.value" color="error" description="Не удалось загрузить пространства"/><p v-if="query.isPending.value">Загружаем пространства…</p><section v-for="project in rows" :key="project.id" class="directory-project"><header><h2><UIcon name="i-lucide-folder-kanban"/>{{project.name}} <small>{{project.spaces.length}}</small></h2><NuxtLink :to="`/projects/${project.id}/spaces`">Открыть проект →</NuxtLink></header><div class="directory-grid"><NuxtLink v-for="space in project.spaces" :key="space.id" :to="`/projects/${project.id}/spaces?space=${space.id}`" class="directory-space"><div class="space-art"><UIcon name="i-lucide-orbit"/></div><h3>{{space.name}}</h3><p>{{space.description||'Пространство проекта'}}</p><footer><span>{{space.object_count}} объектов</span><span>{{space.permission==='viewer'?'Просмотр':'Редактирование'}}</span></footer></NuxtLink><NuxtLink v-if="!project.spaces.length" :to="`/projects/${project.id}/spaces`" class="directory-empty">В проекте пока нет пространств. Открыть проект →</NuxtLink></div></section><p v-if="!query.isPending.value&&!rows.length" class="directory-empty">Ничего не найдено. Попробуйте изменить поиск.</p></main></template>
<style scoped>
.spaces-directory{width:100%;max-width:1400px;padding:30px 20px}.directory-back{color:#94a3b8;font-size:12px}.spaces-directory>header{display:flex;justify-content:space-between;align-items:center;margin:36px 0}.eyebrow{font-size:10px;color:#94a3b8;letter-spacing:.18em}h1{display:flex;align-items:center;gap:16px;font-size:36px;font-weight:650;margin:12px 0}h1 .iconify{color:#8b5cf6}header p{font-size:14px;color:#94a3b8}header>a{font-size:12px;color:#7c3aed}.directory-filters{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:32px}.directory-search{flex:1;min-width:240px}.directory-filters select{font-size:12px;border:1px solid #e2e8f0;background:white;border-radius:10px;padding:8px 12px}.directory-project{margin:30px 0}.directory-project>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}h2{display:flex;align-items:center;gap:10px;font-size:18px;font-weight:600}h2 small{color:#94a3b8;font-size:12px}.directory-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:20px}.directory-space{background:white;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden;transition:transform .15s,box-shadow .15s}.directory-space:hover{transform:translateY(-3px);box-shadow:0 12px 30px #0001}.space-art{height:120px;background:#f5f3ff;background-image:radial-gradient(#ddd6fe 1px,transparent 1px);background-size:18px 18px;display:flex;align-items:center;justify-content:center}.space-art>.iconify{font-size:48px;color:#a78bfa}h3{padding:16px 18px 0;font-size:15px;font-weight:600}.directory-space p{padding:8px 18px;color:#94a3b8;font-size:12px;min-height:50px}.directory-space footer{display:flex;justify-content:space-between;padding:14px 18px;border-top:1px solid #f1f5f9;font-size:10px;color:#94a3b8}.directory-empty{padding:30px;color:#94a3b8;font-size:13px}@media(max-width:650px){.spaces-directory>header{align-items:start;gap:20px}h1{font-size:28px}.directory-project>header{align-items:start;gap:12px}}
</style>
